final_submission.code:
Mesh<Point, double> mesh;
for (RT::Facet it = rt.facets_begin(); it != rt.facets_end(); ++it) {
    if (is_large_facet(rt, *it, threshold)) {
        RT::Cell_handle c = it->first;
        unsigned k = it->second;
        Point p1 = rt.dual(c);
        RT::Cell_handle neighbor = rt.neighbor(c, k);
        if (neighbor != nullptr) {
            Point p2 = rt.dual(neighbor);
            mesh.add_edge(p1, p2);
        }
    }
}
return mesh;

